sysauto_script.script:
/**
 * One-time platform enablement for SafeTrace.
 *
 * Each of these targets a GLOBAL record that a scoped Fluent build cannot
 * declare (the build fails scope validation at upload, or the update-set loader
 * silently skips a private property). Performing them as runtime GlideRecord
 * writes from a scheduled job is the supported way to land them.
 *
 * All three steps are idempotent, and the job deactivates itself once there is
 * nothing left to do.
 *
 * 1. sn_atf.runner.enabled  -> true   (lets the ATF suite actually execute)
 * 2. glide.email.smtp.active -> true  (lets the 11 notifications actually send)
 * 3. Case-form related lists for Case Tasks + Communications
 *
 * NOTE: is_private is deliberately NOT modified on either property. Only the
 * value changes, so the platform's protection of these records is preserved.
 */
;(function runPlatformEnablement() {
    var JOB = 'BFD - Platform enablement'
    var CASE_TABLE = 'x_1755386_safetr_0_bfd_fraud_dispute_case'
    var changes = 0

    // ---------------------------------------------------------------- helpers
    function setProperty(name, value) {
        var gr = new GlideRecord('sys_properties')
        if (!gr.get('name', name)) {
            gs.warn('[' + JOB + '] property not found, skipping: ' + name)
            return false
        }
        if (gr.getValue('value') === value) {
            return false // already correct
        }
        gr.setValue('value', value)
        if (gr.update()) {
            gs.info('[' + JOB + '] ' + name + ' set to ' + value)
            return true
        }
        gs.error('[' + JOB + '] write to ' + name + ' was blocked (ACL / write_roles).')
        return false
    }

    /** Ensures one related-list entry exists under the case form's container. */
    function ensureEntry(containerId, relatedList, position, orderBy) {
        var existing = new GlideRecord('sys_ui_related_list_entry')
        existing.addQuery('list_id', containerId)
        existing.addQuery('related_list', relatedList)
        existing.setLimit(1)
        existing.query()
        if (existing.next()) {
            return false
        }
        var entry = new GlideRecord('sys_ui_related_list_entry')
        entry.initialize()
        entry.setValue('list_id', containerId)
        entry.setValue('related_list', relatedList)
        entry.setValue('position', position)
        if (orderBy) {
            entry.setValue('order_by', orderBy)
        }
        if (entry.insert()) {
            gs.info('[' + JOB + '] related list added: ' + relatedList)
            return true
        }
        gs.error('[' + JOB + '] could not add related list: ' + relatedList)
        return false
    }

    function ensureRelatedLists() {
        var added = 0

        // Find or create the container for the case table's default view.
        var container = new GlideRecord('sys_ui_related_list')
        container.addQuery('name', CASE_TABLE)
        container.addQuery('view', 'Default view')
        container.setLimit(1)
        container.query()

        var containerId = ''
        if (container.next()) {
            containerId = container.getUniqueValue()
        } else {
            var fresh = new GlideRecord('sys_ui_related_list')
            fresh.initialize()
            fresh.setValue('name', CASE_TABLE)
            fresh.setValue('view', 'Default view')
            containerId = '' + fresh.insert()
            if (!containerId) {
                gs.error('[' + JOB + '] could not create the related-list container.')
                return 0
            }
            gs.info('[' + JOB + '] created related-list container for the case form.')
        }

        if (ensureEntry(containerId, 'x_1755386_safetr_0_bfd_case_task.case', 0, 'due_date')) added++
        if (ensureEntry(containerId, 'x_1755386_safetr_0_bfd_case_communication.case', 1, 'sent_at')) added++
        if (ensureEntry(containerId, 'x_1755386_safetr_0_bfd_case_metric_snapshot.case', 2, 'metric_date')) added++

        return added
    }

    // ------------------------------------------------------------------- run
    try {
        if (setProperty('sn_atf.runner.enabled', 'true')) changes++
    } catch (e) {
        gs.error('[' + JOB + '] ATF property: ' + e)
    }

    try {
        if (setProperty('glide.email.smtp.active', 'true')) changes++
    } catch (e) {
        gs.error('[' + JOB + '] email property: ' + e)
    }

    try {
        changes += ensureRelatedLists()
    } catch (e) {
        gs.error('[' + JOB + '] related lists: ' + e)
    }

    if (changes > 0) {
        gs.info('[' + JOB + '] applied ' + changes + ' change(s); re-checking next cycle.')
        return
    }

    // Everything already in place - stand down.
    var job = new GlideRecord('sysauto_script')
    job.addQuery('name', JOB)
    job.setLimit(1)
    job.query()
    if (job.next()) {
        job.setValue('active', false)
        if (job.update()) {
            gs.info('[' + JOB + '] nothing left to enable - job deactivated.')
        }
    }
})()
